export const EVAL_LISTINGS: MaterialListing[] = ROWS.map(
  ([id, sup, family, spec, l, w, t, total, reserved, condition, price, status = 'ACTIVE']) => ({
    id,
    organization_id: sup,
    organization: orgById.get(sup),
    material_family: family,
    material_specification: spec,
    length_mm: l,
    width_mm: w,
    thickness_mm: t,
    total_quantity: total,
    reserved_quantity: reserved,
    available_quantity: total - reserved,
    quantity_unit: 'PIECE',
    condition,
    unit_price_bdt: price,
    city: orgById.get(sup)!.city,
    status,
    created_at: '2026-01-01T00:00:00.000Z',
    updated_at: '2026-01-01T00:00:00.000Z',
  })
);

export interface LabelledRequirement {
  requirement: MaterialRequirement;
  /** Hand-labelled set of technically compatible listings. */
  compatible: string[];
  /** Can the FULL quantity be supplied within the budget (delivered cost)? */
  fulfillable: boolean;
  note: string;
}

const req = (
  id: string,
  buyer: string,
  family: F,
  spec: MaterialSpecification,
  l: number,
  w: number,
  t: number,
  qty: number,
  condition: MaterialRequirement['condition_requirement'],
  split: boolean,
  budget: number | null
): MaterialRequirement => ({
  id,
  organization_id: buyer,
  organization: orgById.get(buyer),
  material_family: family,
  material_specification: spec,
  length_mm: l,
  width_mm: w,
  thickness_mm: t,
  required_quantity: qty,
  quantity_unit: 'PIECE',
  maximum_budget_bdt: budget,
  allow_split_suppliers: split,
  condition_requirement: condition,
  status: 'OPEN',
  created_at: '2026-01-01T00:00:00.000Z',
});

